"use strict";
const $=id=>document.getElementById(id);
const config=window.APP_CONFIG||{};
const APP_SITE_URL=String(config.APP_SITE_URL||"https://riuka1002-a11y.github.io/mangamn/").replace(/\/?$/,"/");
const hasConfig=typeof config.SUPABASE_URL==="string"&&typeof config.SUPABASE_ANON_KEY==="string"&&!config.SUPABASE_URL.includes("YOUR_PROJECT_ID")&&!config.SUPABASE_ANON_KEY.includes("YOUR_SUPABASE_ANON_KEY");
let db=null,authMode="login",toastTimer=null,progressTimer=null;
const state={session:null,user:null,profile:null,teamInfo:null,mangas:[],studioMangas:[],favoriteIds:new Set(),home:{latest:[],top10:[],completed:[]},membershipPlans:[],membership:null,membershipRequests:[],adminRequests:[],adminSuperLikeRequests:[],adminTeams:[],adminDashboard:{summary:{},users:[]},chapterSocial:{comments:[],like_count:0,comment_count:0,super_like_count:0,user_liked:false,team:null},profileStats:{readingMangas:0,chapters:0},currentManga:null,currentChapters:[],managedManga:null,managedChapters:[],reader:{manga:null,chapter:null,chapters:[],pages:[]}};
const DEFAULT_MEMBERSHIP_PLANS=[{code:"month1",name:"1 сарын эрх",duration_months:1,price_mnt:6900,description:"Бүх нийтлэгдсэн манга болон бүлгийг 1 сар унших эрх.",active:true,sort_order:10},{code:"quarter",name:"Улирлын эрх",duration_months:3,price_mnt:26000,description:"Бүх нийтлэгдсэн манга болон бүлгийг 3 сар унших эрх.",active:true,sort_order:20},{code:"halfyear",name:"Хагас жилийн эрх",duration_months:6,price_mnt:38000,description:"Бүх нийтлэгдсэн манга болон бүлгийг 6 сар унших эрх.",active:true,sort_order:30},{code:"year",name:"Жилийн эрх",duration_months:12,price_mnt:81800,description:"Бүх нийтлэгдсэн манга болон бүлгийг 12 сар унших эрх.",active:true,sort_order:40}];
const escapeHTML=(v="")=>String(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
function safeImage(url){if(!url)return"assets/logo.svg";try{const u=new URL(url,location.href);return["http:","https:"].includes(u.protocol)?u.href:"assets/logo.svg"}catch{return"assets/logo.svg"}}
function slugify(text){const base=String(text).normalize("NFKD").toLowerCase().replace(/[^a-z0-9\u0400-\u04ff]+/g,"-").replace(/^-+|-+$/g,"").slice(0,70);return`${base||"manga"}-${crypto.randomUUID().slice(0,8)}`}
function fileExtension(name){const ext=String(name).split(".").pop()?.toLowerCase();return ext&&/^[a-z0-9]+$/.test(ext)?ext:"webp"}
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function isTransientStorageError(error){const status=Number(error?.statusCode||error?.status||0);const message=String(error?.message||"").toLowerCase();return status>=500||status===429||message.includes("network")||message.includes("fetch")||message.includes("timeout")||message.includes("temporar")}
async function uploadWithRetry(bucket,path,file,maxAttempts=3){let lastError=null;for(let attempt=1;attempt<=maxAttempts;attempt++){const{error}=await db.storage.from(bucket).upload(path,file,{cacheControl:"31536000",upsert:false,contentType:file.type});if(!error)return;if(String(error.message||"").toLowerCase().includes("already exists"))throw error;lastError=error;if(attempt>=maxAttempts||!isTransientStorageError(error))break;await sleep(700*attempt)}throw lastError||new Error("Файл байршуулж чадсангүй.")}
async function uploadPrivateChapterImage(path,file){if(!file.type.startsWith("image/"))throw new Error(`${file.name}: зөвхөн зураг оруулна.`);if(file.size>12*1024*1024)throw new Error(`${file.name}: 12MB-аас их байна.`);await uploadWithRetry("chapter-pages",path,file,3);return{image_url:"",storage_path:path,storage_bucket:"chapter-pages"}}
async function resolveChapterPageUrls(pages){const privatePages=pages.filter(p=>p.storage_bucket==="chapter-pages"&&p.storage_path);const signedByPath=new Map();if(privatePages.length){const paths=privatePages.map(p=>p.storage_path);const{data,error}=await db.storage.from("chapter-pages").createSignedUrls(paths,600);if(error)throw error;(data||[]).forEach((item,index)=>{const path=item.path||paths[index],url=item.signedUrl||item.signedURL;if(path&&url)signedByPath.set(path,url)})}return pages.map(p=>({...p,resolved_url:p.storage_bucket==="chapter-pages"?signedByPath.get(p.storage_path)||"":p.image_url}))}
async function removeStoredFiles(files){const groups=new Map();for(const item of files||[]){const path=typeof item==="string"?item:item?.path||item?.storage_path;const bucket=typeof item==="string"?"manga-pages":item?.bucket||item?.storage_bucket||"manga-pages";if(!path)continue;if(!groups.has(bucket))groups.set(bucket,new Set());groups.get(bucket).add(path)}for(const[bucket,paths]of groups){const{error}=await db.storage.from(bucket).remove([...paths]);if(error)throw error}}
function setMessage(el,msg="",type=""){el.textContent=msg;el.className=`form-message${type?` ${type}`:""}`}
function showToast(msg,type=""){const t=$("toast");t.textContent=msg;t.className=`toast${type?` ${type}`:""}`;t.classList.remove("hidden");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add("hidden"),4200)}
function setButtonLoading(btn,on,text="Түр хүлээнэ үү..."){if(on){btn.dataset.originalText=btn.textContent;btn.textContent=text;btn.disabled=true}else{btn.textContent=btn.dataset.originalText||btn.textContent;btn.disabled=false}}
function formatDate(v){return v?new Intl.DateTimeFormat("mn-MN",{year:"numeric",month:"short",day:"numeric"}).format(new Date(v)):""}
function formatMoney(value){return new Intl.NumberFormat("mn-MN").format(Number(value||0))+"₮"}
function daysRemaining(value){if(!value)return 0;return Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/86400000))}
function authRedirectUrl(){return APP_SITE_URL}
function roleLabel(role){if(role==="admin")return"Админ";if(role==="translator")return"Орчуулагч";return"Уншигч"}
function hasReadingAccess(){return ["translator","admin"].includes(state.profile?.role)||Boolean(state.membership&&new Date(state.membership.expires_at)>new Date())}
function registerServiceWorker(){if("serviceWorker"in navigator&&location.protocol.startsWith("http"))addEventListener("load",()=>navigator.serviceWorker.register("./sw.js?v=13.1.0",{updateViaCache:"none"}).catch(()=>{}))}
function configureAuthMode(mode){authMode=mode;const reg=mode==="register";$("loginTab").classList.toggle("hidden",!reg);$("registerTab").classList.toggle("hidden",reg);$("forgotPasswordBtn").classList.toggle("hidden",reg);$("nameField").classList.toggle("hidden",!reg);$("authTitle").textContent=reg?"Шинэ бүртгэл":"Тавтай морил!";$("authSubtitle").textContent=reg?"Шинэ бүртгэл уншигчийн эрхээр үүснэ.":"Та бүртгэлтэй имэйл болон нууц үгээрээ нэвтэрнэ үү.";$("authModeHint").textContent=reg?"Орчуулагчийн эрхийг бүртгүүлсний дараа багийн тусгай кодоор нээнэ.":"Та бүртгүүлсний дараа манга унших боломжтой.";$("authSubmit").textContent=reg?"♙ Бүртгэл үүсгэх":"↪ Нэвтрэх";$("authSubmit").className=`auth-action ${reg?"auth-register":"auth-login"}`;$("password").autocomplete=reg?"new-password":"current-password";setMessage($("authMessage"))}
function updateInviteVisibility(){}
function getOAuthRedirectUrl(){const url=new URL("./",window.location.href);url.search="";url.hash="";return url.href}
async function handleOAuthLogin(provider,button){if(!db){setMessage($("authMessage"),"Эхлээд config.js файлд Supabase URL болон publishable key-г оруулна уу.","error");return}setMessage($("authMessage"));if(authMode==="register"){const role=document.querySelector('input[name="accountRole"]:checked')?.value||"reader",invite=$("inviteCode").value.trim();if(role==="translator"&&!invite){setMessage($("authMessage"),"Орчуулагчийн урилгын кодоо оруулсны дараа сошиал бүртгэлээр үргэлжлүүлнэ үү.","error");return}role==="translator"?localStorage.setItem("pendingTranslatorInvite",invite):localStorage.removeItem("pendingTranslatorInvite")}else localStorage.removeItem("pendingTranslatorInvite");setButtonLoading(button,true,"Холбож байна...");try{const options={redirectTo:getOAuthRedirectUrl()};if(provider==="azure")options.scopes="email";const{error}=await db.auth.signInWithOAuth({provider,options});if(error)throw error}catch(err){setMessage($("authMessage"),err.message||"Сошиал нэвтрэлт эхлүүлэх үед алдаа гарлаа.","error");setButtonLoading(button,false)}}
async function handleAuthSubmit(e){e.preventDefault();if(!db){setMessage($("authMessage"),"Эхлээд config.js файлд Supabase URL болон anon key-г оруулна уу.","error");return}const email=$("email").value.trim(),password=$("password").value,submit=$("authSubmit");setMessage($("authMessage"));if(!email||password.length<8){setMessage($("authMessage"),"Зөв имэйл болон доод тал нь 8 тэмдэгттэй нууц үг оруулна уу.","error");return}setButtonLoading(submit,true);try{if(authMode==="login"){const{error}=await db.auth.signInWithPassword({email,password});if(error)throw error;setMessage($("authMessage"),"Амжилттай нэвтэрлээ.","success");return}const displayName=$("displayName").value.trim();if(displayName.length<2)throw new Error("Нэрээ доод тал нь 2 тэмдэгтээр оруулна уу.");const{data,error}=await db.auth.signUp({email,password,options:{emailRedirectTo:authRedirectUrl(),data:{display_name:displayName}}});if(error)throw error;if(data.session){setMessage($("authMessage"),"Бүртгэл амжилттай үүслээ. Орчуулагч бол Миний булан хэсэгт багийн кодоо оруулна уу.","success")}else setMessage($("authMessage"),"Баталгаажуулах холбоос таны имэйлд илгээгдлээ. Имэйлээ баталгаажуулаад нэвтэрнэ үү.","success")}catch(err){setMessage($("authMessage"),err.message||"Нэвтрэх үед алдаа гарлаа.","error")}finally{setButtonLoading(submit,false)}}
async function loadTeamInfo(){if(!state.user||!state.profile)return;const{data,error}=await db.rpc("get_my_translator_team");if(error){state.teamInfo=null;showToast(`Багийн мэдээлэл ачаалж чадсангүй: ${error.message}`,"error")}else state.teamInfo=data||null;renderTeamAccess()}
function renderTeamAccess(){const card=$("translatorTeamCard"),status=$("translatorTeamStatus"),meta=$("translatorTeamMeta"),form=$("translatorTeamJoinForm");if(!card||!status||!meta||!form||!state.profile)return;const translator=state.profile.role==="translator",admin=state.profile.role==="admin";card.classList.toggle("active",translator||admin);if(admin){status.textContent="Админ эрх идэвхтэй.";meta.textContent="Админ бүх орчуулагчийн хэсэгт хандах боломжтой.";form.classList.add("hidden");return}if(translator){const name=state.teamInfo?.name||"Орчуулагч баг",members=Number(state.teamInfo?.member_count||0),max=Number(state.teamInfo?.max_members||20);status.textContent=`${name} багийн орчуулагчийн эрх идэвхтэй.`;const likes=Number(state.teamInfo?.super_like_count||0),value=Number(state.teamInfo?.super_like_value||0);meta.textContent=`Багийн гишүүд: ${members}/${max} · Super Like: ${likes} (${formatMoney(value)}). Дахин код оруулах шаардлагагүй.`;form.classList.add("hidden")}else{status.textContent="Зөвхөн манайхаас багийн код авсан хэрэглэгч орчуулагчийн эрх нээнэ.";meta.textContent="Нэг кодыг 20 хүртэл тусдаа бүртгэл нэг удаа ашиглаж болно.";form.classList.remove("hidden")}}
async function joinTranslatorTeam(e){e.preventDefault();const code=$("translatorTeamCode").value.trim().toUpperCase(),msg=$("translatorTeamMessage"),btn=e.currentTarget.querySelector('button[type="submit"]');setMessage(msg);if(!code){setMessage(msg,"Багийн кодоо оруулна уу.","error");return}setButtonLoading(btn,true,"Шалгаж байна...");try{const{data,error}=await db.rpc("join_translator_team",{p_team_code:code});if(error)throw error;state.profile=await getProfile(state.user.id);await loadTeamInfo();$("translatorTeamCode").value="";$("studioNav").classList.remove("hidden");renderTeamAccess();renderProfileDashboard();await loadStudio();setMessage(msg,"Орчуулагчийн эрх амжилттай нээгдлээ.","success");showToast("Орчуулагчийн студи нээгдлээ.","success")}catch(err){setMessage(msg,err.message||"Код буруу эсвэл багийн 20 гишүүний лимит дүүрсэн байна.","error")}finally{setButtonLoading(btn,false)}}
async function getProfile(id,retries=3){for(let i=0;i<retries;i++){const{data,error}=await db.from("profiles").select("*").eq("id",id).maybeSingle();if(error)throw error;if(data)return data;await new Promise(r=>setTimeout(r,350))}throw new Error("Хэрэглэгчийн профайл үүсээгүй байна. supabase.sql файлыг ажиллуулсан эсэхээ шалгана уу.")}
async function handleSession(session){state.session=session;state.user=session?.user||null;if(!session){state.profile=null;state.teamInfo=null;state.membership=null;state.membershipRequests=[];state.adminRequests=[];state.adminDashboard={summary:{},users:[]};document.body.classList.add("guest-mode");$("guestView").classList.remove("hidden");$("appView").classList.add("hidden");$("mainNav").classList.add("hidden");$("profileNav").classList.add("hidden");$("logoutBtn").classList.add("hidden");$("userBadge").classList.add("hidden");$("siteFooter").classList.add("hidden");return}try{document.body.classList.remove("guest-mode");state.profile=await getProfile(state.user.id);if(state.profile.account_status==="suspended"){await db.auth.signOut();setMessage($("authMessage"),"Таны бүртгэл админаас түр хаагдсан байна.","error");return}$("guestView").classList.add("hidden");$("appView").classList.remove("hidden");$("mainNav").classList.remove("hidden");$("profileNav").classList.remove("hidden");$("logoutBtn").classList.add("hidden");$("userBadge").classList.add("hidden");$("siteFooter").classList.remove("hidden");$("studioNav").classList.toggle("hidden",state.profile.role!=="translator");$("adminNav").classList.toggle("hidden",state.profile.role!=="admin");showView("library");await Promise.all([loadLibrary(),loadFavorites(),loadHomeSections(),loadMembershipData(),loadTeamInfo()]);await loadProfileDashboard();if(state.profile.role==="translator")await loadStudio()}catch(e){showToast(e.message||"Профайл ачааллах үед алдаа гарлаа.","error")}}
async function loadLibrary(){const{data,error}=await db.from("mangas").select("id,title,slug,description,cover_url,genres,status,series_status,is_featured,created_at,updated_at,translator_id").eq("status","published").order("updated_at",{ascending:false});if(error){showToast(`Номын сан ачаалж чадсангүй: ${error.message}`,"error");return}state.mangas=data||[];renderLibrary();renderFavorites();renderHomeSections()}
async function loadFavorites(){const{data,error}=await db.from("favorites").select("manga_id").eq("user_id",state.user.id);if(error){showToast(`Хадгалсан жагсаалт ачаалж чадсангүй: ${error.message}`,"error");return}state.favoriteIds=new Set((data||[]).map(x=>x.manga_id));renderLibrary();renderFavorites();renderHomeSections();renderProfileDashboard()}
function seriesStatusMeta(value){if(value==="completed")return{label:"Гарч дууссан",className:"completed"};if(value==="hiatus")return{label:"Түр завсарласан",className:"hiatus"};return{label:"Үргэлжилж буй",className:"ongoing"}}
function mangaCardTemplate(m,options={}){const genres=Array.isArray(m.genres)&&m.genres.length?m.genres.join(" · "):"Төрөл оруулаагүй",fav=state.favoriteIds.has(m.id),series=seriesStatusMeta(m.series_status),rank=Number(options.rank||0),hasStats=Object.hasOwn(m,"favorite_count")||Object.hasOwn(m,"latest_chapter"),latestChapter=m.latest_chapter!==null&&m.latest_chapter!==undefined?`Бүлэг ${m.latest_chapter}`:"Бүлэг ороогүй",favoriteCount=Number(m.favorite_count||0),stats=hasStats?`<div class="card-stats"><span>${escapeHTML(latestChapter)}</span><span>♥ ${favoriteCount}</span></div>`:"";return`<article class="manga-card ${rank?"ranked-card":""}"><div class="manga-cover-wrap" data-open-manga="${escapeHTML(m.id)}" tabindex="0" role="button">${rank?`<span class="rank-badge">#${rank}</span>`:""}<img class="manga-cover" src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}" loading="lazy"><span class="series-badge ${series.className}">${series.label}</span><button class="favorite-mini ${fav?"active":""}" data-favorite="${escapeHTML(m.id)}" aria-label="${fav?"Хадгалснаас хасах":"Хадгалах"}">${fav?"♥":"♡"}</button></div><h3 title="${escapeHTML(m.title)}">${escapeHTML(m.title)}</h3><p>${escapeHTML(genres)}</p>${stats}</article>`}
async function loadHomeSections(){const{data,error}=await db.rpc("get_home_sections");if(error){showToast(`Нүүр хэсэг ачаалж чадсангүй: ${error.message}`,"error");state.home={latest:[],top10:[],completed:[]};renderHomeSections();return}state.home={latest:Array.isArray(data?.latest)?data.latest:[],top10:Array.isArray(data?.top10)?data.top10:[],completed:Array.isArray(data?.completed)?data.completed:[]};renderHomeSections()}
function renderHomeSections(){const latest=$("latestGrid"),top=$("top10Grid"),completed=$("completedGrid");if(!latest||!top||!completed)return;latest.innerHTML=state.home.latest.map(m=>mangaCardTemplate(m)).join("");top.innerHTML=state.home.top10.map((m,i)=>mangaCardTemplate(m,{rank:i+1})).join("");completed.innerHTML=state.home.completed.map(m=>mangaCardTemplate(m)).join("");$("latestEmpty").classList.toggle("hidden",state.home.latest.length!==0);$("top10Empty").classList.toggle("hidden",state.home.top10.length!==0);$("completedEmpty").classList.toggle("hidden",state.home.completed.length!==0);$("latestCount").textContent=state.home.latest.length?`${state.home.latest.length} бүтээл`:"";$("completedCount").textContent=state.home.completed.length?`${state.home.completed.length} бүтээл`:""}
function renderLibrary(){const q=$("searchInput").value.trim().toLowerCase(),items=state.mangas.filter(m=>`${m.title} ${(m.genres||[]).join(" ")} ${m.description||""}`.toLowerCase().includes(q));$("libraryGrid").innerHTML=items.map(m=>mangaCardTemplate(m)).join("");$("libraryEmpty").classList.toggle("hidden",items.length!==0);$("libraryCount").textContent=`${items.length} бүтээл`}
function renderFavorites(){const items=state.mangas.filter(m=>state.favoriteIds.has(m.id));$("favoritesGrid").innerHTML=items.map(mangaCardTemplate).join("");$("favoritesEmpty").classList.toggle("hidden",items.length!==0)}
async function toggleFavorite(id){const exists=state.favoriteIds.has(id);let error;if(exists)({error}=await db.from("favorites").delete().eq("user_id",state.user.id).eq("manga_id",id));else({error}=await db.from("favorites").insert({user_id:state.user.id,manga_id:id}));if(error){showToast(error.message,"error");return}exists?state.favoriteIds.delete(id):state.favoriteIds.add(id);renderLibrary();renderFavorites();renderHomeSections();loadHomeSections();if(state.currentManga?.id===id&&$("mangaDialog").open)renderMangaDetail()}
async function openManga(id){const manga=state.mangas.find(x=>x.id===id)||[...state.home.latest,...state.home.top10,...state.home.completed].find(x=>x.id===id);if(!manga)return;const{data,error}=await db.from("chapters").select("id,manga_id,chapter_number,title,published,created_at").eq("manga_id",id).eq("published",true).order("chapter_number");if(error){showToast(error.message,"error");return}state.currentManga=manga;state.currentChapters=data||[];renderMangaDetail();$("mangaDialog").showModal()}
function renderMangaDetail(){const m=state.currentManga;if(!m)return;const fav=state.favoriteIds.has(m.id),chs=state.currentChapters,tags=[`<span class="tag">${escapeHTML(seriesStatusMeta(m.series_status).label)}</span>`,...(m.genres||[]).map(g=>`<span class="tag">${escapeHTML(g)}</span>`)].join(""),rows=chs.length?chs.map(c=>`<button class="chapter-row" data-read-chapter="${escapeHTML(c.id)}"><span><strong>Бүлэг ${escapeHTML(c.chapter_number)}</strong><span>${escapeHTML(c.title||"Нэргүй бүлэг")}</span></span><span>${escapeHTML(formatDate(c.created_at))} →</span></button>`).join(""):`<div class="empty-state"><div class="empty-icon">◌</div><h3>Нийтлэгдсэн бүлэг алга</h3><p>Орчуулагч бүлгээ нийтэлсний дараа энд харагдана.</p></div>`;$("mangaDetail").innerHTML=`<div class="manga-detail-hero"><img class="detail-backdrop" src="${escapeHTML(safeImage(m.cover_url))}" alt=""><div class="detail-shade"></div><img class="detail-cover" src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}"><div class="detail-copy"><span class="eyebrow">Монгол орчуулга</span><h2>${escapeHTML(m.title)}</h2><div class="tag-row">${tags||'<span class="tag">Манга</span>'}</div><p>${escapeHTML(m.description||"Тайлбар оруулаагүй.")}</p><div class="detail-actions"><button class="btn btn-primary" data-read-first="${escapeHTML(m.id)}" ${chs.length?"":"disabled"}>▶ Уншиж эхлэх</button><button class="btn btn-ghost" data-favorite="${escapeHTML(m.id)}">${fav?"♥ Хадгалсан":"♡ Хадгалах"}</button></div></div></div><div class="chapter-section"><h3>Бүлгүүд (${chs.length})</h3><div class="chapter-list">${rows}</div></div>`}
async function openReader(id,chapters=state.currentChapters,manga=state.currentManga){if(!hasReadingAccess()){if($("mangaDialog").open)$("mangaDialog").close();showView("membership");showToast("Бүлэг уншихын тулд идэвхтэй гишүүнчлэл шаардлагатай.","error");return}const chapter=chapters.find(x=>x.id===id);if(!chapter||!manga)return;if($("mangaDialog").open)$("mangaDialog").close();$("readerOverlay").classList.remove("hidden");document.body.style.overflow="hidden";$("readerMangaTitle").textContent=manga.title;$("readerChapterTitle").textContent=`Бүлэг ${chapter.chapter_number}${chapter.title?` — ${chapter.title}`:""}`;$("readerPages").innerHTML='<div class="reader-loading">Хамгаалалттай хуудсуудыг ачаалж байна...</div>';state.reader={manga,chapter,chapters,pages:[]};loadChapterCommunity(id);const idx=chapters.findIndex(x=>x.id===id);$("prevChapterBtn").disabled=idx<=0;$("nextChapterBtn").disabled=idx<0||idx>=chapters.length-1;const[{data:rawPages,error},{data:progress}]=await Promise.all([db.from("chapter_pages").select("id,image_url,storage_path,storage_bucket,page_order").eq("chapter_id",id).order("page_order"),db.from("reading_progress").select("page_index").eq("user_id",state.user.id).eq("chapter_id",id).maybeSingle()]);if(error){$("readerPages").innerHTML=`<div class="reader-loading">${escapeHTML(error.message)}</div>`;return}if(!rawPages?.length){$("readerPages").innerHTML='<div class="reader-loading">Энэ бүлэгт хуудас оруулаагүй байна.</div>';return}let pages;try{pages=await resolveChapterPageUrls(rawPages)}catch(err){$("readerPages").innerHTML=`<div class="reader-loading">Хуудасны түр холбоос үүсгэж чадсангүй: ${escapeHTML(err.message||"")}</div>`;return}if(pages.some(p=>!p.resolved_url)){$("readerPages").innerHTML='<div class="reader-loading">Зарим хуудасны хамгаалалттай холбоос үүссэнгүй. Эрхээ шалгаад дахин оролдоно уу.</div>';return}state.reader.pages=pages;$("readerPages").innerHTML=pages.map((p,i)=>`<img class="reader-page" data-page-index="${i}" src="${escapeHTML(safeImage(p.resolved_url))}" alt="${escapeHTML(manga.title)} ${i+1}-р хуудас" loading="lazy" referrerpolicy="no-referrer">`).join("");const resume=Math.min(Number(progress?.page_index||0),pages.length-1);if(resume>0)setTimeout(()=>document.querySelector(`[data-page-index="${resume}"]`)?.scrollIntoView(),500);else $("readerOverlay").scrollTop=0;await saveReadingProgress(resume)}
async function saveReadingProgress(i=0){const id=state.reader.chapter?.id;if(!id||!state.user)return;await db.from("reading_progress").upsert({user_id:state.user.id,chapter_id:id,page_index:Math.max(0,i),updated_at:new Date().toISOString()},{onConflict:"user_id,chapter_id"})}
function trackReaderProgress(){clearTimeout(progressTimer);progressTimer=setTimeout(()=>{const imgs=[...document.querySelectorAll(".reader-page")];if(!imgs.length)return;let best=0,dist=Infinity;imgs.forEach((im,i)=>{const d=Math.abs(im.getBoundingClientRect().top-90);if(d<dist){dist=d;best=i}});saveReadingProgress(best)},500)}
function closeReader(){trackReaderProgress();$("readerOverlay").classList.add("hidden");document.body.style.overflow="";state.reader={manga:null,chapter:null,chapters:[],pages:[]};state.chapterSocial={comments:[],like_count:0,comment_count:0,super_like_count:0,user_liked:false,team:null}}
function navigateReader(dir){const chs=state.reader.chapters,i=chs.findIndex(x=>x.id===state.reader.chapter?.id),next=chs[i+dir];if(next)openReader(next.id,chs,state.reader.manga)}

function renderStudioTeamSummary(){const root=$("teamStudioSummary");if(!root)return;const team=state.teamInfo;if(!team){root.innerHTML="Багийн мэдээлэл ачаалагдаагүй байна.";return}root.innerHTML=`<strong>${escapeHTML(team.name||"Орчуулагч баг")}</strong> · ${Number(team.member_count||0)}/${Number(team.max_members||20)} гишүүн · Хүлээн авсан Super Like: <strong>${Number(team.super_like_count||0)}</strong> (${escapeHTML(formatMoney(team.super_like_value||0))})`}
function resetCreateMangaDialog(){const form=$("createMangaForm");form?.reset();setMessage($("createMangaMessage"));if($("mangaTitle"))$("mangaTitle").value="";if($("mangaDescription"))$("mangaDescription").value="";if($("createMangaTeamLabel"))$("createMangaTeamLabel").textContent=`Баг: ${state.teamInfo?.name||"Таны орчуулагч баг"}. Энэ бүтээлийг зөвхөн уг багийн гишүүд удирдана.`;$('createMangaDialog').showModal()}
function populateQuickChapterMangas(){const select=$("quickChapterManga");if(!select)return;select.innerHTML='<option value="">Манга сонгоно уу</option>'+state.studioMangas.map(m=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.title)}</option>`).join("")}
function openQuickChapterDialog(){if(!state.studioMangas.length){showToast("Эхлээд багийн мангаа үүсгэнэ үү.","error");return}const form=$("quickCreateChapterForm");form.reset();populateQuickChapterMangas();$("createChapterTeamLabel").textContent=`Баг: ${state.teamInfo?.name||"Таны орчуулагч баг"}. Зөвхөн танай багийн манганууд жагсаалтад харагдана.`;setMessage($("quickChapterMessage"));$("createChapterDialog").showModal()}
async function quickCreateChapter(e){e.preventDefault();const form=e.currentTarget,manga=state.studioMangas.find(m=>m.id===$("quickChapterManga").value),files=[...$("quickChapterPages").files],btn=form.querySelector('button[type="submit"]'),msg=$("quickChapterMessage"),publishAfterUpload=$("quickChapterPublished").checked;if(!manga){setMessage(msg,"Мангаа сонгоно уу.","error");return}if(!files.length){setMessage(msg,"Хуудасны зургууд сонгоно уу.","error");return}if(files.length>250){setMessage(msg,"Нэг бүлэгт хамгийн ихдээ 250 зураг оруулна.","error");return}setButtonLoading(btn,true,"Оруулж байна...");let chapterId=null;const stored=[];try{const{data:c,error}=await db.from("chapters").insert({manga_id:manga.id,chapter_number:Number($("quickChapterNumber").value),title:$("quickChapterTitle").value.trim(),published:false,upload_status:"uploading"}).select().single();if(error)throw error;chapterId=c.id;const rows=[];for(let i=0;i<files.length;i++){const f=files[i],percent=Math.round(((i+1)/files.length)*100);setMessage(msg,`${i+1}/${files.length} хуудас · ${percent}%`);const path=`${state.user.id}/${manga.id}/${c.id}/${String(i+1).padStart(4,"0")}-${crypto.randomUUID()}.${fileExtension(f.name)}`,uploaded=await uploadPrivateChapterImage(path,f);stored.push(uploaded);rows.push({chapter_id:c.id,...uploaded,page_order:i+1})}const{error:pErr}=await db.from("chapter_pages").insert(rows);if(pErr)throw pErr;const{error:readyErr}=await db.from("chapters").update({upload_status:"ready",published:publishAfterUpload,updated_at:new Date().toISOString()}).eq("id",c.id);if(readyErr)throw readyErr;form.reset();$("createChapterDialog").close();showToast(`“${manga.title}” манганы ${c.chapter_number}-р бүлэг хамгаалалттайгаар орлоо.`,"success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}catch(err){try{await removeStoredFiles(stored)}catch{}if(chapterId)await db.from("chapters").delete().eq("id",chapterId);setMessage(msg,err.message||"Бүлэг оруулах үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function loadChapterCommunity(chapterId){const root=$("chapterComments");if(root)root.innerHTML='<div class="comment-empty">Сэтгэгдлүүдийг ачаалж байна...</div>';const{data,error}=await db.rpc("get_chapter_social",{p_chapter_id:chapterId});if(error){showToast(`Сэтгэгдэл ачаалж чадсангүй: ${error.message}`,"error");return}state.chapterSocial={comments:Array.isArray(data?.comments)?data.comments:[],like_count:Number(data?.like_count||0),comment_count:Number(data?.comment_count||0),super_like_count:Number(data?.super_like_count||0),user_liked:Boolean(data?.user_liked),team:data?.team||null};renderChapterCommunity()}
function renderChapterCommunity(){const s=state.chapterSocial;$("chapterLikeCount").textContent=String(s.like_count||0);$("chapterSuperLikeCount").textContent=String(s.super_like_count||0);$("chapterLikeBtn").classList.toggle("active",Boolean(s.user_liked));$("chapterLikeBtn").firstChild.nodeValue=s.user_liked?"♥ ":"♡ ";const root=$("chapterComments");root.innerHTML=s.comments.length?s.comments.map(c=>`<article class="comment-item"><div class="comment-item-head"><div><span class="comment-author">${escapeHTML(c.display_name||"Хэрэглэгч")}</span> <span class="comment-date">${escapeHTML(formatDate(c.created_at))}</span></div>${c.can_delete?`<button class="comment-delete" data-delete-comment="${escapeHTML(c.id)}" type="button">Устгах</button>`:""}</div><p class="comment-body">${escapeHTML(c.body)}</p></article>`).join(""):'<div class="comment-empty">Одоогоор сэтгэгдэл алга. Эхний сэтгэгдлийг үлдээгээрэй.</div>'}
async function toggleChapterLike(){const id=state.reader.chapter?.id;if(!id)return;const{data,error}=await db.rpc("toggle_chapter_like",{p_chapter_id:id});if(error){showToast(error.message,"error");return}state.chapterSocial.user_liked=Boolean(data);state.chapterSocial.like_count=Math.max(0,Number(state.chapterSocial.like_count||0)+(data?1:-1));renderChapterCommunity()}
async function submitChapterComment(e){e.preventDefault();const id=state.reader.chapter?.id,body=$("chapterCommentBody").value.trim(),btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("chapterCommentMessage");setMessage(msg);if(!id||body.length<1){setMessage(msg,"Сэтгэгдлээ бичнэ үү.","error");return}setButtonLoading(btn,true,"Илгээж байна...");try{const{error}=await db.rpc("add_chapter_comment",{p_chapter_id:id,p_body:body});if(error)throw error;$("chapterCommentBody").value="";await loadChapterCommunity(id);setMessage(msg,"Сэтгэгдэл нэмэгдлээ.","success")}catch(err){setMessage(msg,err.message||"Сэтгэгдэл илгээж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}
