function openSuperLikeDialog(){const team=state.chapterSocial.team;if(!team){showToast("Энэ бүлгийн орчуулагч багийн мэдээлэл олдсонгүй.","error");return}$("superLikeForm").reset();$("superLikeQuantity").value="1";updateSuperLikeTotal();$("superLikeTarget").innerHTML=`<strong>${escapeHTML(team.name||"Орчуулагч баг")}</strong><span>${escapeHTML(state.reader.manga?.title||"")} · Бүлэг ${escapeHTML(state.reader.chapter?.chapter_number||"")}</span>`;$("superLikeBank").innerHTML=`<span class="eyebrow">Шилжүүлэх данс</span><h3>${escapeHTML(team.bank_name||"M банк")}</h3><div class="bank-row"><div><span>Данс</span><strong>${escapeHTML(team.bank_account||"8010 28 4219")}</strong></div></div><div class="bank-row"><div><span>IBAN</span><strong>${escapeHTML(team.bank_iban||"MN1000 3900 8010 28 4219")}</strong></div></div><div class="bank-row"><div><span>Эзэмшигч</span><strong>${escapeHTML(team.bank_holder||"Ариун-Эрдэнэ")}</strong></div></div>`;const q=1;$("superLikeReference").value=`${state.profile?.display_name||"user"} · ${state.user?.email||""} · ${q} Super Like`;$("superLikeTransferDate").value=new Date().toISOString().slice(0,10);setMessage($("superLikeMessage"));$("superLikeDialog").showModal()}
function updateSuperLikeTotal(){const q=Math.max(1,Math.min(9999,Number($("superLikeQuantity")?.value||1)));if($("superLikeTotal"))$("superLikeTotal").textContent=formatMoney(q*1000);if($("superLikeReference")&&state.user)$("superLikeReference").value=`${state.profile?.display_name||"user"} · ${state.user.email||""} · ${q} Super Like`}
async function submitSuperLikeRequest(e){e.preventDefault();const team=state.chapterSocial.team,chapter=state.reader.chapter,file=$("superLikeReceipt").files[0],q=Math.max(1,Math.min(9999,Number($("superLikeQuantity").value||1))),sender=$("superLikeSenderName").value.trim(),reference=$("superLikeReference").value.trim(),date=$("superLikeTransferDate").value,btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("superLikeMessage");setMessage(msg);if(!team||!chapter||!file||!sender||!reference||!date){setMessage(msg,"Бүх талбарыг бөглөж, баримтаа сонгоно уу.","error");return}if(file.size>10*1024*1024){setMessage(msg,"Баримт 10MB-аас бага байна.","error");return}setButtonLoading(btn,true,"Илгээж байна...");const path=`${state.user.id}/${crypto.randomUUID()}.${fileExtension(file.name)}`;try{const{error:upErr}=await db.storage.from("super-like-receipts").upload(path,file,{upsert:false,contentType:file.type});if(upErr)throw upErr;const{error}=await db.rpc("submit_super_like_request",{p_chapter_id:chapter.id,p_quantity:q,p_sender_name:sender,p_transfer_reference:reference,p_transfer_date:date,p_receipt_path:path});if(error){await db.storage.from("super-like-receipts").remove([path]);throw error}$("superLikeDialog").close();showToast("Super Like хүсэлт илгээгдлээ. Админ баталгаажуулсны дараа тоонд нэмэгдэнэ.","success")}catch(err){setMessage(msg,err.message||"Хүсэлт илгээж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}

async function loadAdminDashboard(){
  if(state.profile?.role!=="admin")return;
  const{data,error}=await db.rpc("get_admin_dashboard");
  if(error){showToast(`Админ дата ачаалж чадсангүй: ${error.message}`,"error");return}
  state.adminDashboard={summary:data?.summary||{},users:Array.isArray(data?.users)?data.users:[]};
  renderAdminDashboard();
}
function renderAdminDashboard(){
  const s=state.adminDashboard.summary||{};
  const set=(id,value)=>{const el=$(id);if(el)el.textContent=value};
  set("adminMetricUsers",String(Number(s.total_users||0)));
  set("adminMetricNewUsers",`Сүүлийн 30 хоног: ${Number(s.new_users_30d||0)}`);
  set("adminMetricMembers",String(Number(s.active_members||0)));
  set("adminMetricExpiring",`7 хоногт дуусах: ${Number(s.expiring_7d||0)}`);
  set("adminMetricMembershipRevenue",formatMoney(s.membership_revenue||0));
  set("adminMetricMembershipRevenue30",`30 хоногт: ${formatMoney(s.membership_revenue_30d||0)}`);
  set("adminMetricSuperLikeRevenue",formatMoney(s.super_like_revenue||0));
  set("adminMetricTotalRevenue",formatMoney(s.total_revenue||0));
  set("adminMetricPending",String(Number(s.pending_membership_requests||0)+Number(s.pending_super_like_requests||0)));
  set("adminMetricContent",String(Number(s.published_manga||0)));
  set("adminMetricChapterCount",`${Number(s.published_chapters||0)} бүлэг`);
  set("adminMetricTranslators",String(Number(s.translator_users||0)));
  set("adminMetricTeams",`${Number(s.translator_teams||0)} баг`);
  renderAdminUsers();
}
function renderAdminUsers(){
  const root=$("adminUserList"),empty=$("adminUsersEmpty");
  if(!root||!empty)return;
  const query=($("adminUserSearch")?.value||"").trim().toLowerCase();
  const filter=$("adminUserStatusFilter")?.value||"all";
  const users=(state.adminDashboard.users||[]).filter(u=>{
    const hay=`${u.display_name||""} ${u.email||""} ${u.team_name||""}`.toLowerCase();
    if(query&&!hay.includes(query))return false;
    if(filter==="active")return u.account_status==="active";
    if(filter==="suspended")return u.account_status==="suspended";
    if(filter==="member")return Boolean(u.membership_active);
    if(filter==="translator")return u.role==="translator";
    return true;
  });
  root.innerHTML=users.map(u=>{
    const isAdmin=u.role==="admin",active=u.account_status!=="suspended",member=Boolean(u.membership_active);
    const role=roleLabel(u.role),days=Number(u.days_remaining||0);
    const membershipText=member?`${escapeHTML(u.membership_plan_name||"Plus+")} · ${days} хоног үлдсэн`:"Plus+ эрхгүй";
    const statusClass=active?"approved":"rejected";
    return`<article class="admin-user-item">
      <div class="admin-user-main">
        <div class="admin-user-avatar">${escapeHTML((u.display_name||u.email||"U").trim().charAt(0).toUpperCase())}</div>
        <div><h3>${escapeHTML(u.display_name||"Хэрэглэгч")}</h3><p>${escapeHTML(u.email||"")}</p><div class="request-meta"><span>${escapeHTML(role)}</span>${u.team_name?`<span>${escapeHTML(u.team_name)}</span>`:""}<span>${escapeHTML(formatDate(u.created_at))}</span></div></div>
      </div>
      <div class="admin-user-membership"><strong>${membershipText}</strong><small>${u.membership_expires_at?`Дуусах: ${escapeHTML(formatDate(u.membership_expires_at))}`:"Идэвхтэй багц байхгүй"}</small></div>
      <div class="admin-user-actions">
        <span class="status-pill ${statusClass}">${active?"Идэвхтэй":"Түр хаасан"}</span>
        ${isAdmin?'<span class="admin-lock-label">Үндсэн админ</span>':`<button class="btn btn-ghost" type="button" data-admin-user-status="${escapeHTML(u.id)}" data-next-status="${active?"suspended":"active"}">${active?"Түр хаах":"Идэвхжүүлэх"}</button><button class="btn btn-ghost" type="button" data-admin-membership="${escapeHTML(u.id)}" data-membership-action="add_days">+ Хоног</button>${member?`<button class="btn btn-danger" type="button" data-admin-membership="${escapeHTML(u.id)}" data-membership-action="revoke">Эрх цуцлах</button>`:""}`}
      </div>
    </article>`;
  }).join("");
  empty.classList.toggle("hidden",users.length!==0);
}
async function adminSetUserStatus(userId,status){
  const verb=status==="suspended"?"түр хаах":"идэвхжүүлэх";
  if(!confirm(`Энэ хэрэглэгчийг ${verb} үү?`))return;
  const{error}=await db.rpc("admin_set_user_status",{p_user_id:userId,p_status:status});
  if(error){showToast(error.message,"error");return}
  showToast(status==="suspended"?"Хэрэглэгч түр хаагдлаа.":"Хэрэглэгч идэвхжлээ.","success");
  await loadAdminDashboard();
}
async function adminAdjustMembership(userId,action){
  let days=0;
  if(action==="add_days"){
    const value=prompt("Хэдэн хоногийн Plus+ эрх нэмэх вэ?","30");
    if(value===null)return;
    days=Number(value);
    if(!Number.isInteger(days)||days<1||days>3650){showToast("1-3650 хоногийн тоо оруулна уу.","error");return}
  }else if(!confirm("Энэ хэрэглэгчийн Plus+ эрхийг одоо цуцлах уу?"))return;
  const{error}=await db.rpc("admin_adjust_membership",{p_user_id:userId,p_action:action,p_days:days});
  if(error){showToast(error.message,"error");return}
  showToast(action==="add_days"?`${days} хоногийн эрх нэмэгдлээ.`:"Plus+ эрх цуцлагдлаа.","success");
  await Promise.all([loadAdminDashboard(),loadAdminRequests()]);
}
async function refreshAdminAll(){
  await Promise.all([loadAdminDashboard(),loadAdminRequests(),loadAdminSuperLikeRequests(),loadAdminTeams()]);
  showToast("Админ мэдээлэл шинэчлэгдлээ.","success");
}

async function loadAdminTeams(){if(state.profile?.role!=="admin")return;const{data,error}=await db.rpc("get_admin_translator_teams");if(error){showToast(error.message,"error");return}state.adminTeams=Array.isArray(data)?data:[];renderAdminTeams()}
function renderAdminTeams(){const root=$("adminTeamList");if(!root)return;root.innerHTML=state.adminTeams.length?state.adminTeams.map(t=>`<article class="admin-team-item"><h3>${escapeHTML(t.name)}</h3><p>Гишүүн: ${Number(t.member_count||0)}/${Number(t.max_members||20)} · Манга: ${Number(t.manga_count||0)}</p><p>Super Like: ${Number(t.super_like_count||0)} (${escapeHTML(formatMoney(t.super_like_value||0))})</p><p>${escapeHTML(t.bank_name||"")} · ${escapeHTML(t.bank_account||"")} · ${escapeHTML(t.bank_holder||"")}</p></article>`).join(""):'<div class="section-empty">Баг үүсгээгүй байна.</div>'}
async function createAdminTeam(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),msg=$("adminTeamMessage");setMessage(msg);setButtonLoading(btn,true,"Үүсгэж байна...");try{const{error}=await db.rpc("admin_create_translator_team",{p_name:$("adminTeamName").value.trim(),p_code:$("adminTeamCode").value.trim(),p_max_members:Number($("adminTeamMax").value||20),p_bank_name:$("adminTeamBank").value.trim(),p_bank_account:$("adminTeamAccount").value.trim(),p_bank_iban:$("adminTeamIban").value.trim(),p_bank_holder:$("adminTeamHolder").value.trim()});if(error)throw error;form.reset();$("adminTeamMax").value="20";$("adminTeamBank").value="M банк";setMessage(msg,"Баг үүслээ. Кодыг зөвхөн тухайн багт өгнө үү.","success");await Promise.all([loadAdminTeams(),loadAdminDashboard()])}catch(err){setMessage(msg,err.message||"Баг үүсгэж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}
async function loadAdminSuperLikeRequests(){if(state.profile?.role!=="admin")return;const{data,error}=await db.rpc("get_admin_super_like_requests");if(error){showToast(error.message,"error");return}state.adminSuperLikeRequests=Array.isArray(data)?data:[];renderAdminSuperLikeRequests()}
function renderAdminSuperLikeRequests(){const root=$("adminSuperLikeRequests");if(!root)return;root.innerHTML=state.adminSuperLikeRequests.length?state.adminSuperLikeRequests.map(r=>{const meta=membershipStatusMeta(r.status);return`<article class="admin-request superlike-request"><div class="admin-request-details"><h3>${escapeHTML(r.user_name)} → ${escapeHTML(r.team_name)}</h3><p>${Number(r.quantity)} Super Like · ${escapeHTML(formatMoney(r.amount_mnt))} · ${escapeHTML(r.manga_title)} / Бүлэг ${escapeHTML(r.chapter_number)}</p><p>Гүйлгээ: ${escapeHTML(r.transfer_reference)}</p><div class="request-meta"><span>${escapeHTML(formatDate(r.created_at))}</span><span class="status-pill ${meta.className}">${meta.label}</span></div></div><div class="admin-request-actions"><button class="btn btn-ghost" data-open-super-receipt="${escapeHTML(r.receipt_path)}" type="button">Баримт</button>${r.status==="pending"?`<button class="btn btn-primary" data-review-superlike="${escapeHTML(r.id)}" data-super-action="approve" type="button">Зөвшөөрөх</button><button class="btn btn-danger" data-review-superlike="${escapeHTML(r.id)}" data-super-action="reject" type="button">Татгалзах</button>`:""}</div></article>`}).join(""):'<div class="section-empty">Super Like хүсэлт алга.</div>'}
async function reviewSuperLikeRequest(id,approve){if(!confirm(`Энэ Super Like хүсэлтийг ${approve?"зөвшөөрөх":"татгалзах"} уу?`))return;const note=prompt("Админы тайлбар (заавал биш):","")||"";const{error}=await db.rpc("review_super_like_request",{p_request_id:id,p_approve:approve,p_admin_note:note});if(error){showToast(error.message,"error");return}showToast(approve?"Super Like баталгаажлаа.":"Хүсэлт татгалзагдлаа.","success");await Promise.all([loadAdminSuperLikeRequests(),loadAdminDashboard()])}
async function openReceiptPreview(bucket,path,title="Төлбөрийн баримт"){
  const dialog=$("receiptPreviewDialog"),frame=$("receiptPreviewFrame"),loading=$("receiptPreviewLoading"),openLink=$("receiptPreviewOpen"),downloadLink=$("receiptPreviewDownload");
  if(!dialog||!frame){showToast("Баримт харах цонх олдсонгүй. index.html файлаа v10.2 хувилбараар солино уу.","error");return}
  $("receiptPreviewTitle").textContent=title;
  frame.classList.add("hidden");
  frame.removeAttribute("src");
  loading.textContent="Баримтыг ачаалж байна...";
  loading.classList.remove("hidden");
  openLink.classList.add("hidden");
  downloadLink.classList.add("hidden");
  if(!dialog.open)dialog.showModal();
  try{
    const{data,error}=await db.storage.from(bucket).createSignedUrl(path,600,{download:false});
    if(error)throw error;
    if(!data?.signedUrl)throw new Error("Signed URL үүссэнгүй.");
    const signedUrl=data.signedUrl;
    frame.src=signedUrl;
    openLink.href=signedUrl;
    downloadLink.href=signedUrl+(signedUrl.includes("?")?"&":"?")+"download=1";
    openLink.classList.remove("hidden");
    downloadLink.classList.remove("hidden");
    frame.classList.remove("hidden");
    loading.classList.add("hidden");
  }catch(err){
    loading.textContent=`Баримт нээж чадсангүй: ${err?.message||"Тодорхойгүй алдаа"}`;
    showToast(`Баримт нээх алдаа: ${err?.message||"Тодорхойгүй алдаа"}`,"error");
  }
}

async function openSuperLikeReceipt(path){return openReceiptPreview("super-like-receipts",path,"Super Like төлбөрийн баримт")}

async function loadMembershipData(){if(!state.user)return;const[plansRes,membershipRes,requestsRes]=await Promise.all([db.from("membership_plans").select("*").eq("active",true).order("sort_order"),db.from("memberships").select("*").eq("user_id",state.user.id).maybeSingle(),db.from("membership_requests").select("*").eq("user_id",state.user.id).order("created_at",{ascending:false}).limit(20)]);if(plansRes.error)showToast(`Багц ачааллах алдаа: ${plansRes.error.message}`,"error");if(membershipRes.error)showToast(membershipRes.error.message,"error");if(requestsRes.error)showToast(requestsRes.error.message,"error");state.membershipPlans=plansRes.data?.length?plansRes.data:DEFAULT_MEMBERSHIP_PLANS;state.membership=membershipRes.data||null;state.membershipRequests=requestsRes.data||[];renderMembership();renderProfileDashboard()}
function membershipStatusMeta(status){if(status==="approved")return{label:"Баталгаажсан",className:"approved"};if(status==="rejected")return{label:"Татгалзсан",className:"rejected"};return{label:"Шалгаж байна",className:"pending"}}
function renderMembership(){const status=$("membershipStatus"),plans=$("membershipPlans"),select=$("membershipPlanSelect"),requests=$("membershipRequests");if(!status||!plans||!select||!requests)return;const active=Boolean(state.membership&&new Date(state.membership.expires_at)>new Date()),pending=state.membershipRequests.some(r=>r.status==="pending");if(["translator","admin"].includes(state.profile?.role)){status.className="membership-status-card active";status.innerHTML=`<span class="eyebrow">Тусгай эрх</span><h3>${roleLabel(state.profile.role)} эрх идэвхтэй</h3><p>Таны эрхээр бүх нийтлэгдсэн бүлгийг унших боломжтой.</p>`}else if(active){status.className="membership-status-card active";status.innerHTML=`<span class="eyebrow">Идэвхтэй гишүүн</span><h3>Унших эрх нээлттэй</h3><p><strong>${daysRemaining(state.membership.expires_at)} хоног үлдсэн.</strong> Эрх ${escapeHTML(formatDate(state.membership.expires_at))} хүртэл хүчинтэй.</p>`}else if(pending){status.className="membership-status-card pending";status.innerHTML=`<span class="eyebrow">Хүлээгдэж байна</span><h3>Төлбөрийн хүсэлтийг шалгаж байна</h3><p>Админ банкны гүйлгээ болон баримтыг баталгаажуулсны дараа эрх автоматаар нээгдэнэ.</p>`}else{status.className="membership-status-card";status.innerHTML=`<span class="eyebrow">Эрх идэвхгүй</span><h3>Бүлэг уншихын тулд багц сонгоно уу</h3><p>Манганы жагсаалт харах боломжтой. Бүлгийн зургууд зөвхөн идэвхтэй гишүүнчлэлтэй үед нээгдэнэ.</p>`}plans.innerHTML=state.membershipPlans.map(p=>`<article class="membership-plan" data-plan-card="${escapeHTML(p.code)}"><span class="eyebrow">${escapeHTML(p.duration_months)} сар</span><h3>${escapeHTML(p.name)}</h3><div class="membership-plan-price">${escapeHTML(formatMoney(p.price_mnt))} <small>/ нийт</small></div><p>${escapeHTML(p.description||`${p.duration_months} сарын унших эрх`)}</p><button class="btn btn-primary" type="button" data-select-plan="${escapeHTML(p.code)}">Сонгох</button></article>`).join("");select.innerHTML='<option value="">Багц сонгоно уу</option>'+state.membershipPlans.map(p=>`<option value="${escapeHTML(p.code)}">${escapeHTML(p.name)} — ${escapeHTML(formatMoney(p.price_mnt))}</option>`).join("");requests.innerHTML=state.membershipRequests.length?state.membershipRequests.map(r=>{const plan=state.membershipPlans.find(p=>p.code===r.plan_code),meta=membershipStatusMeta(r.status);return`<article class="request-item"><div><h3>${escapeHTML(plan?.name||r.plan_code)} · ${escapeHTML(formatMoney(r.amount_mnt))}</h3><div class="request-meta"><span>${escapeHTML(formatDate(r.created_at))}</span><span>${escapeHTML(r.transfer_reference)}</span>${r.admin_note?`<span>Тайлбар: ${escapeHTML(r.admin_note)}</span>`:""}</div></div><span class="status-pill ${meta.className}">${meta.label}</span></article>`}).join(""):'<div class="section-empty">Одоогоор төлбөрийн хүсэлт илгээгээгүй байна.</div>';const today=new Date().toISOString().slice(0,10);if(!$("membershipTransferDate").value)$("membershipTransferDate").value=today}
function selectMembershipPlan(code){const plan=state.membershipPlans.find(p=>p.code===code);if(!plan)return;$("membershipPlanSelect").value=code;document.querySelectorAll("[data-plan-card]").forEach(el=>el.classList.toggle("selected",el.dataset.planCard===code));$("transferMeaningExample").textContent=`${state.profile?.display_name||"username"} · ${state.user?.email||"email"} · ${plan.duration_months} сар`;$("membershipReference").value=`${state.profile?.display_name||""} · ${state.user?.email||""} · ${plan.duration_months} сар`;$("membershipRequestForm").scrollIntoView({behavior:"smooth",block:"center"})}
async function submitMembershipRequest(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),msg=$("membershipMessage"),planCode=$("membershipPlanSelect").value,sender=$("membershipSenderName").value.trim(),reference=$("membershipReference").value.trim(),date=$("membershipTransferDate").value,file=$("membershipReceipt").files[0];setMessage(msg);if(!planCode||!sender||!reference||!date||!file){setMessage(msg,"Бүх талбарыг бөглөж, төлбөрийн баримтаа сонгоно уу.","error");return}const allowed=["image/jpeg","image/png","image/webp","application/pdf"];if(!allowed.includes(file.type)){setMessage(msg,"Баримт JPEG, PNG, WEBP эсвэл PDF байна.","error");return}if(file.size>10*1024*1024){setMessage(msg,"Баримтын хэмжээ 10MB-аас бага байна.","error");return}setButtonLoading(btn,true,"Илгээж байна...");const ext=fileExtension(file.name),path=`${state.user.id}/${crypto.randomUUID()}.${ext}`;try{const{error:uploadError}=await db.storage.from("membership-receipts").upload(path,file,{upsert:false,contentType:file.type});if(uploadError)throw uploadError;const{error}=await db.rpc("submit_membership_request",{p_plan_code:planCode,p_sender_name:sender,p_transfer_reference:reference,p_transfer_date:date,p_receipt_path:path});if(error){await db.storage.from("membership-receipts").remove([path]);throw error}form.reset();setMessage(msg,"Хүсэлт амжилттай илгээгдлээ. Админ баталгаажуулахыг хүлээнэ үү.","success");await loadMembershipData()}catch(err){setMessage(msg,err.message||"Хүсэлт илгээх үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function loadAdminRequests(){if(state.profile?.role!=="admin")return;const{data,error}=await db.from("membership_requests").select("*").order("created_at",{ascending:false}).limit(100);if(error){showToast(error.message,"error");return}const ids=[...new Set((data||[]).map(r=>r.user_id))];let profiles=[];if(ids.length){const res=await db.from("profiles").select("id,display_name").in("id",ids);if(res.error)showToast(res.error.message,"error");else profiles=res.data||[]}const profileMap=new Map(profiles.map(p=>[p.id,p]));state.adminRequests=(data||[]).map(r=>({...r,display_name:profileMap.get(r.user_id)?.display_name||"Хэрэглэгч"}));renderAdminRequests()}
function renderAdminRequests(){const root=$("adminRequests");if(!root)return;const filter=$("adminRequestFilter")?.value||"all",items=filter==="all"?state.adminRequests:state.adminRequests.filter(r=>r.status===filter);root.innerHTML=items.length?items.map(r=>{const plan=state.membershipPlans.find(p=>p.code===r.plan_code),meta=membershipStatusMeta(r.status);return`<article class="admin-request"><div class="admin-request-details"><h3>${escapeHTML(r.display_name)} · ${escapeHTML(plan?.name||r.plan_code)}</h3><p>${escapeHTML(formatMoney(r.amount_mnt))} · ${escapeHTML(r.sender_name)} · ${escapeHTML(r.transfer_date)}</p><p>Гүйлгээний утга: ${escapeHTML(r.transfer_reference)}</p><div class="request-meta"><span>${escapeHTML(formatDate(r.created_at))}</span><span class="status-pill ${meta.className}">${meta.label}</span>${r.admin_note?`<span>Админы тайлбар: ${escapeHTML(r.admin_note)}</span>`:""}</div></div><div class="admin-request-actions"><button class="btn btn-ghost" type="button" data-open-receipt="${escapeHTML(r.receipt_path)}">Баримт</button>${r.status==="pending"?`<button class="btn btn-primary" type="button" data-review-request="${escapeHTML(r.id)}" data-review-action="approve">Зөвшөөрөх</button><button class="btn btn-danger" type="button" data-review-request="${escapeHTML(r.id)}" data-review-action="reject">Татгалзах</button>`:""}</div></article>`}).join(""):'<div class="empty-state"><div class="empty-icon">✓</div><h3>Хүсэлт алга</h3><p>Шинэ төлбөрийн хүсэлт ирэхэд энд харагдана.</p></div>'}
async function openMembershipReceipt(path){return openReceiptPreview("membership-receipts",path,"Гишүүнчлэлийн төлбөрийн баримт")}
async function reviewMembershipRequest(id,approve){const verb=approve?"зөвшөөрөх":"татгалзах";if(!confirm(`Энэ хүсэлтийг ${verb} үү?`))return;const note=prompt("Админы тайлбар (заавал биш):","")||"";const{error}=await db.rpc("review_membership_request",{p_request_id:id,p_approve:approve,p_admin_note:note});if(error){showToast(error.message,"error");return}showToast(approve?"Гишүүнчлэлийн эрх нээгдлээ.":"Хүсэлтэд татгалзлаа.","success");await Promise.all([loadAdminRequests(),loadAdminDashboard()])}
async function copyText(value){try{await navigator.clipboard.writeText(value);showToast("Хуулагдлаа.","success")}catch{showToast("Хуулах боломжгүй байна.","error")}}
async function loadStudio(){let query=db.from("mangas").select("id,title,slug,description,cover_url,cover_path,genres,status,series_status,is_featured,created_at,updated_at,translator_id,team_id").order("updated_at",{ascending:false});query=state.profile?.translator_team_id?query.eq("team_id",state.profile.translator_team_id):query.eq("translator_id",state.user.id);const{data,error}=await query;if(error){showToast(`Студи ачаалж чадсангүй: ${error.message}`,"error");return}state.studioMangas=data||[];renderStudio();populateQuickChapterMangas();renderStudioTeamSummary()}
function renderStudio(){$("studioGrid").innerHTML=state.studioMangas.map(m=>{const tags=(m.genres||[]).map(g=>`<span class="tag">${escapeHTML(g)}</span>`).join("");return`<article class="studio-item"><img src="${escapeHTML(safeImage(m.cover_url))}" alt="${escapeHTML(m.title)}"><div class="studio-meta"><h3>${escapeHTML(m.title)}</h3><p>${m.status==="published"?"Нийтлэгдсэн":"Ноорог"} · ${seriesStatusMeta(m.series_status).label} · ${escapeHTML(formatDate(m.updated_at||m.created_at))}</p><div class="tag-row">${tags||'<span class="tag">Төрөлгүй</span>'}</div></div><div class="studio-actions"><button class="btn btn-ghost" data-manage-manga="${escapeHTML(m.id)}">Удирдах</button><button class="btn btn-ghost" data-toggle-publish="${escapeHTML(m.id)}">${m.status==="published"?"Нуух":"Нийтлэх"}</button><button class="btn btn-danger" data-delete-manga="${escapeHTML(m.id)}">Устгах</button></div></article>`}).join("");$("studioEmpty").classList.toggle("hidden",state.studioMangas.length!==0)}
async function uploadImage(path,file){if(!file.type.startsWith("image/"))throw new Error(`${file.name}: зөвхөн зураг оруулна.`);if(file.size>12*1024*1024)throw new Error(`${file.name}: 12MB-аас их байна.`);await uploadWithRetry("manga-pages",path,file,3);return db.storage.from("manga-pages").getPublicUrl(path).data.publicUrl}
async function createManga(e){e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type="submit"]'),msg=$("createMangaMessage"),file=$("mangaCover").files[0],title=$("mangaTitle").value.trim(),description=$("mangaDescription").value.trim(),genres=$("mangaGenres").value.split(",").map(x=>x.trim()).filter(Boolean).slice(0,12),status=$("mangaPublished").checked?"published":"draft",seriesStatus=$("mangaSeriesStatus").value,isFeatured=$("mangaFeatured").checked;if(!file){setMessage(msg,"Нүүр зураг сонгоно уу.","error");return}setButtonLoading(submit,true,"Үүсгэж байна...");let id=null,path=null;try{const{data:m,error}=await db.from("mangas").insert({translator_id:state.user.id,team_id:state.profile?.translator_team_id||null,title,slug:slugify(title),description,genres,status,series_status:seriesStatus,is_featured:isFeatured}).select().single();if(error)throw error;id=m.id;path=`${state.user.id}/${m.id}/cover-${crypto.randomUUID()}.${fileExtension(file.name)}`;const url=await uploadImage(path,file);const{error:upErr}=await db.from("mangas").update({cover_url:url,cover_path:path}).eq("id",m.id);if(upErr)throw upErr;form.reset();$("createMangaDialog").close();showToast("Манга амжилттай үүслээ.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}catch(err){if(path)await db.storage.from("manga-pages").remove([path]);if(id)await db.from("mangas").delete().eq("id",id);setMessage(msg,err.message||"Манга үүсгэх үед алдаа гарлаа.","error")}finally{setButtonLoading(submit,false)}}
async function toggleMangaPublish(id){const m=state.studioMangas.find(x=>x.id===id);if(!m)return;const status=m.status==="published"?"draft":"published",{error}=await db.from("mangas").update({status,updated_at:new Date().toISOString()}).eq("id",id);if(error){showToast(error.message,"error");return}showToast(status==="published"?"Манга нийтлэгдлээ.":"Манга номын сангаас нуугдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}
async function deleteManga(id){const m=state.studioMangas.find(x=>x.id===id);if(!m||!confirm(`“${m.title}” манга болон бүх бүлгийг бүр мөсөн устгах уу?`))return;try{const{data:chs,error}=await db.from("chapters").select("id").eq("manga_id",id);if(error)throw error;const ids=(chs||[]).map(x=>x.id);let stored=m.cover_path?[{bucket:"manga-pages",path:m.cover_path}]:[];if(ids.length){const{data:pages,error:pErr}=await db.from("chapter_pages").select("storage_path,storage_bucket").in("chapter_id",ids);if(pErr)throw pErr;stored=stored.concat((pages||[]).map(x=>({bucket:x.storage_bucket||"manga-pages",path:x.storage_path})).filter(x=>x.path))}if(stored.length)await removeStoredFiles(stored);const{error:dErr}=await db.from("mangas").delete().eq("id",id);if(dErr)throw dErr;showToast("Манга устгагдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()])}catch(err){showToast(err.message||"Устгах үед алдаа гарлаа.","error")}}
async function openManageManga(id){const m=state.studioMangas.find(x=>x.id===id);if(!m)return;const{data,error}=await db.from("chapters").select("*").eq("manga_id",id).order("chapter_number");if(error){showToast(error.message,"error");return}state.managedManga=m;state.managedChapters=data||[];renderManageManga();$("manageMangaDialog").showModal()}
function renderManageManga(){const m=state.managedManga;if(!m)return;const rows=state.managedChapters.map(c=>`<div class="manage-chapter-row"><div><strong>Бүлэг ${escapeHTML(c.chapter_number)} — ${escapeHTML(c.title||"Нэргүй")}</strong><small>${c.published?"Нийтлэгдсэн":"Ноорог"} · ${escapeHTML(formatDate(c.created_at))}</small></div><div class="mini-actions"><button class="mini-btn" data-toggle-chapter="${escapeHTML(c.id)}">${c.published?"◉":"○"}</button><button class="mini-btn" data-delete-chapter="${escapeHTML(c.id)}">⌫</button></div></div>`).join("");$("manageMangaContent").innerHTML=`<div class="manage-header"><span class="eyebrow">Бүтээл удирдах</span><h2>${escapeHTML(m.title)}</h2><p>Манганы мэдээллийг засах, шинэ бүлэг нэмэх, нийтлэх төлвийг удирдана.</p></div><div class="manage-body"><div class="manage-card"><h3>Манганы мэдээлэл</h3><form id="editMangaForm" class="stack-form"><label class="field"><span>Нэр</span><input id="editMangaTitle" value="${escapeHTML(m.title)}" required maxlength="120"></label><label class="field"><span>Тайлбар</span><textarea id="editMangaDescription" required maxlength="1200" rows="5">${escapeHTML(m.description||"")}</textarea></label><label class="field"><span>Төрөл</span><input id="editMangaGenres" value="${escapeHTML((m.genres||[]).join(", "))}" maxlength="180"></label><label class="field"><span>Цувралын төлөв</span><select id="editMangaSeriesStatus"><option value="ongoing" ${m.series_status==="ongoing"?"selected":""}>Үргэлжилж буй</option><option value="completed" ${m.series_status==="completed"?"selected":""}>Гарч дууссан</option><option value="hiatus" ${m.series_status==="hiatus"?"selected":""}>Түр завсарласан</option></select></label><label class="field"><span>Шинэ нүүр зураг (заавал биш)</span><input id="editMangaCover" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="toggle-row"><input id="editMangaFeatured" type="checkbox" ${m.is_featured?"checked":""}> Онцлох хэсэгт харуулах</label><label class="toggle-row"><input id="editMangaPublished" type="checkbox" ${m.status==="published"?"checked":""}> Нийтлэгдсэн</label><button class="btn btn-primary btn-block" type="submit">Хадгалах</button><p id="editMangaMessage" class="form-message"></p></form></div><div><div class="manage-card"><h3>Шинэ бүлэг</h3><form id="createChapterForm" class="stack-form"><label class="field"><span>Бүлгийн дугаар</span><input id="chapterNumber" type="number" min="0" step="0.1" required placeholder="1"></label><label class="field"><span>Бүлгийн нэр</span><input id="chapterTitle" maxlength="160" placeholder="Эхлэл"></label><label class="field"><span>Хуудасны зургууд</span><input id="chapterPages" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><label class="toggle-row"><input id="chapterPublished" type="checkbox"> Шууд нийтлэх</label><button class="btn btn-primary btn-block" type="submit">Бүлэг оруулах</button><p id="createChapterMessage" class="form-message"></p></form></div><div class="manage-card" style="margin-top:18px"><h3>Бүлгүүд (${state.managedChapters.length})</h3><div class="manage-chapters">${rows||'<p class="form-message">Бүлэг оруулаагүй байна.</p>'}</div></div></div></div>`;$("editMangaForm").addEventListener("submit",editManagedManga);$("createChapterForm").addEventListener("submit",createChapter)}
async function editManagedManga(e){e.preventDefault();const btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("editMangaMessage"),m=state.managedManga,file=$("editMangaCover").files[0];let newPath=null;setButtonLoading(btn,true,"Хадгалж байна...");try{const updates={title:$("editMangaTitle").value.trim(),description:$("editMangaDescription").value.trim(),genres:$("editMangaGenres").value.split(",").map(x=>x.trim()).filter(Boolean).slice(0,12),series_status:$("editMangaSeriesStatus").value,is_featured:$("editMangaFeatured").checked,status:$("editMangaPublished").checked?"published":"draft",updated_at:new Date().toISOString()};if(file){newPath=`${state.user.id}/${m.id}/cover-${crypto.randomUUID()}.${fileExtension(file.name)}`;updates.cover_url=await uploadImage(newPath,file);updates.cover_path=newPath}const{data,error}=await db.from("mangas").update(updates).eq("id",m.id).select().single();if(error)throw error;if(file&&m.cover_path)await db.storage.from("manga-pages").remove([m.cover_path]);state.managedManga=data;setMessage(msg,"Мэдээлэл хадгалагдлаа.","success");await Promise.all([loadStudio(),loadLibrary(),loadHomeSections()]);setTimeout(renderManageManga,400)}catch(err){if(newPath)await db.storage.from("manga-pages").remove([newPath]);setMessage(msg,err.message||"Хадгалах үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function createChapter(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),msg=$("createChapterMessage"),files=[...$("chapterPages").files],m=state.managedManga,publishAfterUpload=$("chapterPublished").checked;if(!files.length){setMessage(msg,"Доод тал нь нэг хуудасны зураг сонгоно уу.","error");return}if(files.length>250){setMessage(msg,"Нэг бүлэгт хамгийн ихдээ 250 зураг оруулна.","error");return}setButtonLoading(btn,true,"Бүлэг оруулж байна...");let chapterId=null;const stored=[];try{const{data:c,error}=await db.from("chapters").insert({manga_id:m.id,chapter_number:Number($("chapterNumber").value),title:$("chapterTitle").value.trim(),published:false,upload_status:"uploading"}).select().single();if(error)throw error;chapterId=c.id;const rows=[];for(let i=0;i<files.length;i++){const f=files[i],percent=Math.round(((i+1)/files.length)*100);setMessage(msg,`${i+1}/${files.length} хуудас · ${percent}%`);const path=`${state.user.id}/${m.id}/${c.id}/${String(i+1).padStart(4,"0")}-${crypto.randomUUID()}.${fileExtension(f.name)}`,uploaded=await uploadPrivateChapterImage(path,f);stored.push(uploaded);rows.push({chapter_id:c.id,...uploaded,page_order:i+1})}const{error:pErr}=await db.from("chapter_pages").insert(rows);if(pErr)throw pErr;const{error:readyErr}=await db.from("chapters").update({upload_status:"ready",published:publishAfterUpload,updated_at:new Date().toISOString()}).eq("id",c.id);if(readyErr)throw readyErr;form.reset();const{data}=await db.from("chapters").select("*").eq("manga_id",m.id).order("chapter_number");state.managedChapters=data||[];renderManageManga();showToast("Бүлэг хамгаалалттайгаар амжилттай орлоо.","success");await Promise.all([loadLibrary(),loadHomeSections()])}catch(err){try{await removeStoredFiles(stored)}catch{}if(chapterId)await db.from("chapters").delete().eq("id",chapterId);setMessage(msg,err.message||"Бүлэг оруулах үед алдаа гарлаа.","error")}finally{setButtonLoading(btn,false)}}
async function toggleChapter(id){const c=state.managedChapters.find(x=>x.id===id);if(!c)return;if(c.upload_status&&c.upload_status!=="ready"){showToast("Upload бүрэн дуусаагүй бүлгийг нийтлэх боломжгүй.","error");return}const{error}=await db.from("chapters").update({published:!c.published}).eq("id",id);if(error){showToast(error.message,"error");return}c.published=!c.published;renderManageManga();showToast(c.published?"Бүлэг нийтлэгдлээ.":"Бүлэг нуугдлаа.","success");await Promise.all([loadLibrary(),loadHomeSections()])}
async function deleteChapter(id){const c=state.managedChapters.find(x=>x.id===id);if(!c||!confirm(`Бүлэг ${c.chapter_number}-г бүх хуудастай нь устгах уу?`))return;try{const{data:pages,error}=await db.from("chapter_pages").select("storage_path,storage_bucket").eq("chapter_id",id);if(error)throw error;const stored=(pages||[]).map(x=>({bucket:x.storage_bucket||"manga-pages",path:x.storage_path})).filter(x=>x.path);if(stored.length)await removeStoredFiles(stored);const{error:dErr}=await db.from("chapters").delete().eq("id",id);if(dErr)throw dErr;state.managedChapters=state.managedChapters.filter(x=>x.id!==id);renderManageManga();showToast("Бүлэг устгагдлаа.","success")}catch(err){showToast(err.message||"Устгах үед алдаа гарлаа.","error")}}
async function loadProfileDashboard(){if(!state.user||!state.profile)return;let rows=[];const expanded=await db.from("reading_progress").select("chapter_id,updated_at,chapters(manga_id)").eq("user_id",state.user.id).order("updated_at",{ascending:false});if(expanded.error){const fallback=await db.from("reading_progress").select("chapter_id,updated_at").eq("user_id",state.user.id).order("updated_at",{ascending:false});if(!fallback.error)rows=fallback.data||[]}else rows=expanded.data||[];const mangaIds=new Set(rows.map(r=>r.chapters?.manga_id).filter(Boolean));state.profileStats={readingMangas:mangaIds.size||rows.length,chapters:rows.length};renderProfileDashboard()}
function renderProfileDashboard(){if(!state.profile||!state.user)return;renderTeamAccess();const display=state.profile.display_name||state.user.email?.split("@")[0]||"Хэрэглэгч",initial=display.trim().charAt(0).toUpperCase()||"U";if($("profileAvatar"))$("profileAvatar").textContent=initial;if($("profileLargeAvatar"))$("profileLargeAvatar").textContent=initial;if($("profileDisplayName"))$("profileDisplayName").textContent=display;if($("profileEmail"))$("profileEmail").textContent=state.user.email||"";if($("profileRole"))$("profileRole").textContent=roleLabel(state.profile.role);if($("profileReadingCount"))$("profileReadingCount").textContent=String(state.profileStats.readingMangas||0);if($("profileFavoriteCount"))$("profileFavoriteCount").textContent=String(state.favoriteIds.size||0);if($("profileChapterCount"))$("profileChapterCount").textContent=String(state.profileStats.chapters||0);const active=Boolean(state.membership&&new Date(state.membership.expires_at)>new Date()),pending=state.membershipRequests.some(r=>r.status==="pending"),text=$("profileMembershipText"),sub=$("profileMembershipSubtext");if(!text||!sub)return;if($("profileMembershipDays"))$("profileMembershipDays").classList.add("hidden");if(["translator","admin"].includes(state.profile.role)){text.textContent=`${roleLabel(state.profile.role)} эрх идэвхтэй`;sub.textContent="Таны тусгай эрхээр бүх нийтлэгдсэн бүлгийг унших боломжтой."}else if(active){text.textContent=`Plus+ эрх ${formatDate(state.membership.expires_at)} хүртэл идэвхтэй`;if($("profileMembershipDays")){$("profileMembershipDays").textContent=`${daysRemaining(state.membership.expires_at)} хоног үлдсэн`;$("profileMembershipDays").classList.remove("hidden")}sub.textContent="Та бүх нийтлэгдсэн манганы бүлгийг унших боломжтой."}else if(pending){text.textContent="Төлбөрийн хүсэлтийг шалгаж байна";sub.textContent="Админ баталгаажуулсны дараа Plus+ эрх автоматаар нээгдэнэ."}else{text.textContent="Танд одоогоор Plus+ эрх байхгүй.";sub.textContent="Plus+ эрх авснаар бүх бүлгийг унших боломжтой."}}
async function requestPasswordReset(){const email=$("email").value.trim();setMessage($("authMessage"));if(!email){setMessage($("authMessage"),"Нууц үг сэргээх имэйл хаягаа оруулна уу.","error");$("email").focus();return}if(!db){setMessage($("authMessage"),"Supabase холболт бэлэн биш байна.","error");return}const btn=$("forgotPasswordBtn");setButtonLoading(btn,true,"Илгээж байна...");try{const{error}=await db.auth.resetPasswordForEmail(email,{redirectTo:authRedirectUrl()});if(error)throw error;setMessage($("authMessage"),"Нууц үг шинэчлэх холбоос таны имэйл рүү илгээгдлээ.","success")}catch(err){setMessage($("authMessage"),err.message||"Сэргээх холбоос илгээж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}
async function updateRecoveredPassword(e){e.preventDefault();const password=$("newPassword").value,btn=e.currentTarget.querySelector('button[type="submit"]'),msg=$("resetPasswordMessage");setMessage(msg);if(password.length<8){setMessage(msg,"Нууц үг доод тал нь 8 тэмдэгт байна.","error");return}setButtonLoading(btn,true,"Хадгалж байна...");try{const{error}=await db.auth.updateUser({password});if(error)throw error;setMessage(msg,"Нууц үг амжилттай шинэчлэгдлээ.","success");setTimeout(()=>$("resetPasswordDialog").close(),900)}catch(err){setMessage(msg,err.message||"Нууц үг шинэчилж чадсангүй.","error")}finally{setButtonLoading(btn,false)}}

function showView(view){const allowed=["library","favorites","membership","studio","admin","profile"];if(!allowed.includes(view)||view==="studio"&&state.profile?.role!=="translator"||view==="admin"&&state.profile?.role!=="admin")return;allowed.forEach(x=>$(x+"View")?.classList.toggle("hidden",x!==view));document.querySelectorAll(".nav-link[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));window.scrollTo({top:0,behavior:"smooth"});if(view==="favorites")renderFavorites();if(view==="membership")loadMembershipData();if(view==="studio")loadStudio();if(view==="admin"){loadAdminDashboard();loadAdminRequests();loadAdminSuperLikeRequests();loadAdminTeams()}if(view==="profile"){loadProfileDashboard();loadTeamInfo()}}
function handleDocumentClick(e){const refreshAll=e.target.closest("[data-refresh-admin-all]");if(refreshAll){refreshAdminAll();return}const userStatus=e.target.closest("[data-admin-user-status]");if(userStatus){adminSetUserStatus(userStatus.dataset.adminUserStatus,userStatus.dataset.nextStatus);return}const membershipAction=e.target.closest("[data-admin-membership]");if(membershipAction){adminAdjustMembership(membershipAction.dataset.adminMembership,membershipAction.dataset.membershipAction);return}const delComment=e.target.closest("[data-delete-comment]");if(delComment){deleteChapterComment(delComment.dataset.deleteComment);return}const refreshTeams=e.target.closest("[data-refresh-teams]");if(refreshTeams){loadAdminTeams();return}const refreshSL=e.target.closest("[data-refresh-superlikes]");if(refreshSL){loadAdminSuperLikeRequests();return}const slReceipt=e.target.closest("[data-open-super-receipt]");if(slReceipt){openSuperLikeReceipt(slReceipt.dataset.openSuperReceipt);return}const slReview=e.target.closest("[data-review-superlike]");if(slReview){reviewSuperLikeRequest(slReview.dataset.reviewSuperlike,slReview.dataset.superAction==="approve");return}const target=e.target.closest("[data-view-target]");if(target){e.preventDefault();showView(target.dataset.viewTarget);return}const close=e.target.closest("[data-close-dialog]");if(close){$(close.dataset.closeDialog)?.close();return}const copy=e.target.closest("[data-copy-text]");if(copy){copyText(copy.dataset.copyText);return}const plan=e.target.closest("[data-select-plan]");if(plan){selectMembershipPlan(plan.dataset.selectPlan);return}const refreshMember=e.target.closest("[data-refresh-membership]");if(refreshMember){loadMembershipData();return}const refreshAdmin=e.target.closest("[data-refresh-admin]");if(refreshAdmin){loadAdminRequests();return}const receipt=e.target.closest("[data-open-receipt]");if(receipt){openMembershipReceipt(receipt.dataset.openReceipt);return}const review=e.target.closest("[data-review-request]");if(review){reviewMembershipRequest(review.dataset.reviewRequest,review.dataset.reviewAction==="approve");return}const fav=e.target.closest("[data-favorite]");if(fav){e.stopPropagation();toggleFavorite(fav.dataset.favorite);return}const manga=e.target.closest("[data-open-manga]");if(manga){openManga(manga.dataset.openManga);return}const read=e.target.closest("[data-read-chapter]");if(read){openReader(read.dataset.readChapter);return}const first=e.target.closest("[data-read-first]");if(first&&state.currentChapters[0]){openReader(state.currentChapters[0].id);return}const manage=e.target.closest("[data-manage-manga]");if(manage){openManageManga(manage.dataset.manageManga);return}const pub=e.target.closest("[data-toggle-publish]");if(pub){toggleMangaPublish(pub.dataset.togglePublish);return}const del=e.target.closest("[data-delete-manga]");if(del){deleteManga(del.dataset.deleteManga);return}const tc=e.target.closest("[data-toggle-chapter]");if(tc){toggleChapter(tc.dataset.toggleChapter);return}const dc=e.target.closest("[data-delete-chapter]");if(dc)deleteChapter(dc.dataset.deleteChapter)}
function bindEvents(){$("loginTab").addEventListener("click",()=>configureAuthMode("login"));$("registerTab").addEventListener("click",()=>configureAuthMode("register"));$("forgotPasswordBtn").addEventListener("click",requestPasswordReset);$("resetPasswordForm").addEventListener("submit",updateRecoveredPassword);$("authForm").addEventListener("submit",handleAuthSubmit);$("translatorTeamJoinForm")?.addEventListener("submit",joinTranslatorTeam);$("logoutBtn").addEventListener("click",()=>db?.auth.signOut());$("profileLogoutBtn").addEventListener("click",()=>db?.auth.signOut());$("searchInput").addEventListener("input",renderLibrary);$("adminUserSearch")?.addEventListener("input",renderAdminUsers);$("adminUserStatusFilter")?.addEventListener("change",renderAdminUsers);$("adminRequestFilter")?.addEventListener("change",renderAdminRequests);$("membershipPlanSelect").addEventListener("change",e=>selectMembershipPlan(e.target.value));$("membershipRequestForm").addEventListener("submit",submitMembershipRequest);$("openCreateMangaBtn").addEventListener("click",resetCreateMangaDialog);$("openCreateChapterBtn")?.addEventListener("click",openQuickChapterDialog);$("quickCreateChapterForm")?.addEventListener("submit",quickCreateChapter);$("createMangaForm").addEventListener("submit",createManga);$("closeReaderBtn").addEventListener("click",closeReader);$("prevChapterBtn").addEventListener("click",()=>navigateReader(-1));$("nextChapterBtn").addEventListener("click",()=>navigateReader(1));$("readerTopBtn").addEventListener("click",()=>$("readerOverlay").scrollTo({top:0,behavior:"smooth"}));$("readerOverlay").addEventListener("scroll",trackReaderProgress,{passive:true});$("chapterLikeBtn")?.addEventListener("click",toggleChapterLike);$("chapterCommentForm")?.addEventListener("submit",submitChapterComment);$("openSuperLikeBtn")?.addEventListener("click",openSuperLikeDialog);$("superLikeQuantity")?.addEventListener("input",updateSuperLikeTotal);$("superLikeForm")?.addEventListener("submit",submitSuperLikeRequest);$("adminCreateTeamForm")?.addEventListener("submit",createAdminTeam);document.addEventListener("click",handleDocumentClick);document.querySelectorAll(".nav-link[data-view]").forEach(b=>b.addEventListener("click",()=>showView(b.dataset.view)));document.querySelectorAll("dialog").forEach(d=>d.addEventListener("click",e=>{if(e.target===d)d.close()}));document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("readerOverlay").classList.contains("hidden"))closeReader()})}
async function init(){document.body.classList.add("guest-mode");bindEvents();registerServiceWorker();configureAuthMode("login");if(!hasConfig){$("setupNotice").textContent="Системийг ажиллуулахын тулд config.js файлд Supabase URL болон anon key-г оруулна уу.";$("setupNotice").classList.remove("hidden");return}try{db=window.supabase.createClient(config.SUPABASE_URL,config.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});db.auth.onAuthStateChange((event,session)=>setTimeout(()=>{if(event==="PASSWORD_RECOVERY")$("resetPasswordDialog").showModal();handleSession(session)},0));const recoveryLink=location.hash.includes("type=recovery")||location.search.includes("type=recovery");const{data,error}=await db.auth.getSession();if(error)throw error;await handleSession(data.session);if(location.hash.includes("access_token")||location.hash.includes("refresh_token")||location.search.includes("code="))history.replaceState({},document.title,location.pathname);if(recoveryLink)$("resetPasswordDialog").showModal()}catch(err){$("setupNotice").textContent=`Supabase холболтын алдаа: ${err.message}`;$("setupNotice").classList.remove("hidden")}}
init();
